package com.sakti.banking.service; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.stereotype.Service; import java.time.Duration; import java.security.SecureRandom; @Service public class SecurityCacheService { private final StringRedisTemplate redis; private final SecureRandom random=new SecureRandom(); public SecurityCacheService(StringRedisTemplate r){redis=r;} public String issueOtp(String key){String otp=String.format("%06d",random.nextInt(1_000_000)); redis.opsForValue().set("otp:"+key,otp,Duration.ofMinutes(5)); return otp;} public boolean verifyOtp(String key,String value){String stored=redis.opsForValue().get("otp:"+key); boolean ok=stored!=null&&stored.equals(value); if(ok)redis.delete("otp:"+key); return ok;} public long incrementFailedLogin(String email){Long v=redis.opsForValue().increment("login-fail:"+email.toLowerCase()); redis.expire("login-fail:"+email.toLowerCase(),Duration.ofMinutes(15)); return v==null?0:v;} }
